/**
 * Versioned wire contract for Cursor-managed store operations.
 *
 * Evolution rules (the compat contract): additive optional fields only; no
 * renames, no retypes, no semantic reuse of an old field; unknown fields are
 * ignored, never rejected; removing a field means deprecating it in place
 * forever. A breaking change means a new `v`, and the server keeps serving
 * every previous `v`.
 */
import * as z from "zod/v4";
export const STORE_API_PROTOCOL_VERSION = 1;
/** Managed storage endpoint, with one trailing segment per call. */
export const STORE_API_PATH = "/internal/agentsdk/store/api";
export const STORE_API_MEMORY_APPEND_CALL = "memory.append";
/**
 * Semantic cap on one serialized memory record. Text fields are truncated
 * client-side (`memoryHook` default 2000 chars per field), so a well-formed
 * record is a few KiB; 16 KiB is generous headroom, not a target. The cap is
 * part of the wire contract but not the schema. The service enforces it as a
 * typed 4xx, and the client checks it before sending a request.
 */
export const MEMORY_APPEND_MAX_RECORD_BYTES = 16 * 1024;
/** Serialized size of a record, as counted against the byte cap. */
export function serializedRecordBytes(record) {
    return new TextEncoder().encode(JSON.stringify(record)).byteLength;
}
/**
 * Wire schema for {@link TurnMemoryRecordWire}. Per-field caps are
 * deliberately absent: the client truncates text at authoring time and
 * {@link MEMORY_APPEND_MAX_RECORD_BYTES} bounds the whole record.
 */
export const turnMemoryRecordWireSchema = z
    .object({
    at: z.string().min(1),
    sessionId: z.string().min(1),
    channelId: z.string().min(1),
    status: z.enum(["completed", "failed"]),
    title: z.string().optional(),
    sdkAgentId: z.string().optional(),
    userMessage: z.string().optional(),
    result: z.string().optional(),
    usage: z.object({}).passthrough().optional(),
})
    .passthrough();
/**
 * `memory.append` payload shape. The agent name becomes a store key segment
 * on the server, so it must be exactly one segment. Unknown payload fields
 * are stripped (= ignored), per the evolution rules. The service owns the
 * byte cap because it is a semantic limit rather than part of the shape.
 */
export const memoryAppendPayloadSchema = z.object({
    agent: z
        .string()
        .min(1)
        .max(256)
        .refine((name) => !name.includes("/") && !name.includes("\\") && name !== "." && name !== "..", {
        message: "agent must be a single store key segment",
    }),
    record: turnMemoryRecordWireSchema,
});
/** The whole request body. Unknown envelope fields are stripped (= ignored). */
export const memoryAppendEnvelopeSchema = z.object({
    v: z.literal(STORE_API_PROTOCOL_VERSION),
    call: z.literal(STORE_API_MEMORY_APPEND_CALL),
    payload: memoryAppendPayloadSchema,
});
/**
 * Success body. Failures answer the store surface's standard error JSON
 * (`{ code, error }`) with a matching HTTP status.
 */
export const memoryAppendResponseSchema = z.object({
    v: z.literal(STORE_API_PROTOCOL_VERSION),
    ok: z.literal(true),
});
export const STORE_API_MEMORY_READ_CALL = "memory.read";
/**
 * `memory.read` payload shape — the same single-segment agent name rule as
 * `memory.append`, since the name addresses the same journal key family.
 */
export const memoryReadPayloadSchema = z.object({
    agent: z
        .string()
        .min(1)
        .max(256)
        .refine((name) => !name.includes("/") && !name.includes("\\") && name !== "." && name !== "..", {
        message: "agent must be a single store key segment",
    }),
});
/** The whole request body. Unknown envelope fields are stripped (= ignored). */
export const memoryReadEnvelopeSchema = z.object({
    v: z.literal(STORE_API_PROTOCOL_VERSION),
    call: z.literal(STORE_API_MEMORY_READ_CALL),
    payload: memoryReadPayloadSchema,
});
/**
 * Success body. Failures answer the store surface's standard error JSON
 * (`{ code, error }`) with a matching HTTP status.
 */
export const memoryReadResponseSchema = z.object({
    v: z.literal(STORE_API_PROTOCOL_VERSION),
    ok: z.literal(true),
    journal: z
        .object({
        url: z.string().min(1),
        expiresAt: z.string().min(1),
    })
        .nullable(),
});
/**
 * Live session relay: the engine posts batches of session events, and the
 * service keeps them only while a viewer is watching that session. The
 * stored transcript stays the durable copy.
 */
export const STORE_API_SESSION_LIVE_CALL = "session.live";
/**
 * Cap on one serialized live event. A larger event crosses as a stub with
 * `liveTruncated: true`; viewers reread the stored transcript after the turn.
 */
export const SESSION_LIVE_MAX_EVENT_BYTES = 16 * 1024;
/** Cap on one batch's serialized `events`, enforced on both sides. */
export const SESSION_LIVE_MAX_BATCH_BYTES = 256 * 1024;
export const SESSION_LIVE_MAX_BATCH_EVENTS = 500;
export const sessionLiveEventWireSchema = z
    .object({
    index: z.number().int().min(0),
    type: z.string().min(1),
})
    .passthrough();
export const sessionLivePayloadSchema = z.object({
    sessionId: z.string().regex(/^[A-Za-z0-9_-]{1,128}$/),
    events: z.array(sessionLiveEventWireSchema).max(SESSION_LIVE_MAX_BATCH_EVENTS),
});
/** The whole request body. Unknown envelope fields are stripped (= ignored). */
export const sessionLiveEnvelopeSchema = z.object({
    v: z.literal(STORE_API_PROTOCOL_VERSION),
    call: z.literal(STORE_API_SESSION_LIVE_CALL),
    payload: sessionLivePayloadSchema,
});
export const sessionLiveResponseSchema = z.object({
    v: z.literal(STORE_API_PROTOCOL_VERSION),
    ok: z.literal(true),
    subscribed: z.boolean(),
    recheckAfterMs: z.number().int().min(0),
    replayFromIndex: z.number().int().min(0).nullable(),
});
